// A very large function body (1200 statement repetitions generated by macros) (self-checking).
// Expected values: IEEE 1800-2017 22.5.1 (`define macros with nested expansion), 13.4 (functions),
// 11.3/11.6 (32-bit two's complement int arithmetic wraps), 21.3 ($sformatf %0d), 6.16 (string concatenation,
// len).  Reference model: the same recurrence sum' = sum + (sum + 3 + len("x")) written as a plain loop
// (since name == "a1" the first branch of every repetition is taken).
`define S1 if (name == "a1") begin sum = sum + f(sum, 3, "x"); s = {s, $sformatf("%0d", sum)}; end else if (s.len() > 3 && sum > 5) s = s.substr(1, 2);
`define S10 `S1 `S1 `S1 `S1 `S1 `S1 `S1 `S1 `S1 `S1
`define S100 `S10 `S10 `S10 `S10 `S10 `S10 `S10 `S10 `S10 `S10
module svbigunit1;
  function automatic int f(int a, int b, string c); return a + b + c.len(); endfunction
  function automatic int big(string name);
    int sum = 1; string s = "";
    `S100 `S100 `S100 `S100 `S100 `S100 `S100 `S100 `S100 `S100 `S100 `S100 
    return sum + s.len();
  endfunction
  function automatic int model();
    int sum = 1; string s = "";
    for (int i = 0; i < 1200; i++) begin
      sum = sum + (sum + 3 + 1);
      s = {s, $sformatf("%0d", sum)};
    end
    return sum + s.len();
  endfunction
  initial begin
    int got, exp;
    got = big("a1");
    exp = model();
    if (got !== exp) $error("big(a1) = %0d, expected %0d", got, exp);
    else $display("PASSED");
  end
endmodule
